import logging


class Bts(object):

    _CONNECTION_LOG_MSG = 'Connecting to {} BTS with address: {}, port: {}, username: {}, password: {}'
    _DISCONNECTION_LOG_MSG = 'Disconnecting from {} BTS with address: {}, port: {}, username: {}, password: {}'
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self, alias):
        """
        :param alias: connection alias which will be used during creation of BTS connection
        :type alias: str
        """
        self._api = None
        self._ip = None
        self._port = None
        self._username = None
        self._password = None
        self._alias = alias
        self._logger = logging.getLogger()

    @property
    def alias(self):
        """
        :return: connection alias used during communication with BTS
        :rtype: str
        """
        return self._alias

    def connect_to(self, log_dir):
        """
        Creates connection with BTS to allow further communication.

        :param log_dir: path to directory where logs from BTS communication will be stored
        :type log_dir: str
        """
        self._connect_to(log_dir=log_dir)

    def get_statuses(self, dist_name, timeout):
        """
        Fetches current statuses from BTS.

        :param dist_name: runtime distName of component for which current statuses should be read
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type dist_name: str
        :param timeout: time in which BTS should respond with current statuses
        :type timeout: float or int
        :return: current statuses read from BTS
        :rtype: {str: str or {str: str}}
        """
        return self._get_statuses(dist_name=dist_name, timeout=timeout)

    def disconnect(self):
        """
        Destroys connection with BTS to stop further communication.
        """
        self._disconnect()

    def _connect_to(self, log_dir):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                                                 self._connect_to.__name__))

    def _get_statuses(self, dist_name, timeout):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                                                 self._get_statuses.__name__))

    def _disconnect(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                                                 self._disconnect.__name__))
